{
  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])

    node_map = {}
    children = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = n
        children.setdefault(nid, [])
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children[pid].append(n['id'])

    symbol_counts = {}
    for n in nodes:
        sym = n['symbol']
        symbol_counts[sym] = symbol_counts.get(sym, 0) + 1

    removed = set()
    removal_order = []

    all_nodes = [(n['depth'], n['id']) for n in nodes]
    all_nodes.sort(key=lambda x: (-x[0], x[1]))

    def remove_subtree(nid):
        if nid in removed:
            return
        removed.add(nid)
        sym = node_map[nid]['symbol']
        symbol_counts[sym] -= 1
        if symbol_counts[sym] == 0:
            del symbol_counts[sym]
        for child in children[nid]:
            remove_subtree(child)

    for depth, nid in all_nodes:
        if nid in removed:
            continue
        n = node_map[nid]
        if not n['removable']:
            continue

        subtree_symbols = {}
        def count_subtree(node_id):
            sub = node_map[node_id]
            sym = sub['symbol']
            subtree_symbols[sym] = subtree_symbols.get(sym, 0) + 1
            for child in children[node_id]:
                if child not in removed:
                    count_subtree(child)
        count_subtree(nid)

        can_remove = True
        for sym in required_symbols:
            total = symbol_counts.get(sym, 0)
            in_sub = subtree_symbols.get(sym, 0)
            if total - in_sub <= 0:
                can_remove = False
                break

        if can_remove:
            remove_subtree(nid)
            removal_order.append(nid)

    retain_ids = [n['id'] for n in nodes if n['id'] not in removed]
    retain_ids.sort()
    return {'retained_ids': retain_ids, 'removal_order': removal_order}"
}
